import{_ as t,I as o,g as a,j as s}from"./chunks/framework.CjoWWfVe.js";const u=JSON.parse('{"title":"Что реализовано и что ожидать","description":"Текущий статус проекта ОмниКрафт ЕРП и дорожная карта развития.","frontmatter":{"title":"Что реализовано и что ожидать","description":"Текущий статус проекта ОмниКрафт ЕРП и дорожная карта развития.","order":4},"headers":[],"relativePath":"ru/docs/roadmap.md","filePath":"ru/docs/roadmap.md"}'),n={name:"ru/docs/roadmap.md"};function l(e,r,i,g,d,p){return o(),a("div",null,[...r[0]||(r[0]=[s('<h1 id="🚀-что-реализовано-и-что-ожидать" tabindex="-1">🚀 Что реализовано и что ожидать <a class="header-anchor" href="#🚀-что-реализовано-и-что-ожидать" aria-label="Permalink to &quot;🚀 Что реализовано и что ожидать&quot;">​</a></h1><p>ОмниКрафт ЕРП — это активно развивающийся продукт. Мы регулярно выпускаем обновления, опираясь на собственную практику в ремесле и отзывы пользователей. На этой странице вы можете узнать, что уже стабильно работает, а какие функции находятся в разработке.</p><h2 id="✅-текущии-статус-стабильное-ядро-версия-1-0-x" tabindex="-1">✅ Текущий статус: Стабильное ядро (Версия 1.0.x) <a class="header-anchor" href="#✅-текущии-статус-стабильное-ядро-версия-1-0-x" aria-label="Permalink to &quot;✅ Текущий статус: Стабильное ядро (Версия 1.0.x)&quot;">​</a></h2><p>На данный момент полностью реализован и отлажен <strong>Основной производственный конвейер</strong>. Базовая версия программы позволяет вести полноценный управленческий учет микропредприятия:</p><ul><li><strong>Имущество:</strong> Умная амортизация оборудования и расчет остаточной стоимости мастерской.</li><li><strong>Склад (МАК):</strong> Партионный учет сырья с распределением стоимости доставки на себестоимость материалов без искажений.</li><li><strong>Калькулятор:</strong> Конструктор рецептов с учетом труда мастера и накладных расходов.</li><li><strong>Производство:</strong> Динамический верстак с умным каскадным пересчетом резервов сырья (очередь ФИФО).</li><li><strong>Сбыт:</strong> Управление каналами продаж, наценками и POS-терминал с учетом стоимости логистики (оплачивает клиент или мастерская).</li><li><strong>Финансы:</strong> Глобальный управленческий баланс (Капитал), кассовая книга (ДДС) и продвинутая графическая аналитика (Финансовый пульс, Точка безубыточности).</li><li><strong>Безопасность:</strong> Встроены ротационные ГФС-копии, режим журналирования базы данных ВАЛ и защита от потери информации при сбоях питания.</li></ul><p>Все эти функции доступны в рамках <a href="./licenses">Базовой (Стандарт) лицензии</a>.</p><hr><h2 id="✅-реализовано-про-режим-и-экосистема" tabindex="-1">✅ Реализовано: ПРО-режим и Экосистема <a class="header-anchor" href="#✅-реализовано-про-режим-и-экосистема" aria-label="Permalink to &quot;✅ Реализовано: ПРО-режим и Экосистема&quot;">​</a></h2><p>В рамках расширения возможностей системы до корпоративного уровня (версии ПРО) были успешно внедрены и стабильно работают следующие функции:</p><ul><li><strong>Мультипространства (Multi-Workspaces):</strong> Создание независимых баз данных для ведения нескольких разных бизнесов (например, кожевенная мастерская и розничная торговля) с мгновенным переключением.</li><li><strong>Глобальная сводная панель «Мой капитал»:</strong> Революционный подход к учету личных финансов. Программа консолидирует прибыль всех ваших бизнесов и автоматически вычисляет повседневные траты на жизнь через дельту капиталов (без необходимости вбивать каждый чек).</li><li><strong>Маркетплейс и Сквозные модули:</strong> Гибкая архитектура плагинов (Add-ons) с нулевым влиянием на производительность компьютера.</li><li><strong>Модуль «Амбассадор»:</strong> Встроенная система органического продвижения с автогенерацией UTM-ссылок, QR-кодов на чеках и внутренним магазином бонусов.</li></ul><hr><h2 id="🔮-в-разработке-кастомные-модули-и-расширения-дорожная-карта" tabindex="-1">🔮 В разработке: Кастомные модули и расширения (Дорожная карта) <a class="header-anchor" href="#🔮-в-разработке-кастомные-модули-и-расширения-дорожная-карта" aria-label="Permalink to &quot;🔮 В разработке: Кастомные модули и расширения (Дорожная карта)&quot;">​</a></h2><p>Фундамент экосистемы заложен. Дальнейшее развитие проекта будет сфокусировано на создании <strong>специализированных сквозных модулей</strong>, которые будут разрабатываться по мере появления запросов от мастеров.</p><p>Возможные будущие расширения:</p><ul><li><strong>Модуль «Выкройки» (Patterns):</strong> Каталогизация лекал, расчет площади раскроя кожи, привязка PDF/CAD чертежей.</li><li><strong>Модуль «Услуги и Кастом» (Services):</strong> Учет индивидуальных ремонтов и пошива на заказ с оценкой затраченного времени без классической витрины товаров.</li><li><strong>Модуль «Маркетинг и ROI»:</strong> Учет рекламных бюджетов мастера с автоматическим расчетом окупаемости каждого канала продаж.</li></ul><blockquote><p><strong>Индивидуальная кастомная разработка</strong> Архитектура маркетплейса позволяет разрабатывать уникальные закрытые модули под ваши индивидуальные бизнес-процессы (например, специфические процессы для ювелиров, керамистов или столярных мастерских) по запросу сообщества.</p></blockquote><blockquote><p><strong>Автоматические обновления</strong> Программа имеет встроенную систему проверки версий. При запуске она сама сообщит вам, если вышло обновление с новыми функциями, и предложит ссылку на скачивание. Ваши базы данных при обновлении переносятся автоматически и бесшовно.</p></blockquote>',17)])])}const h=t(n,[["render",l]]);export{u as __pageData,h as default};
